# Patterns compiled when the program runs: each is given to re.compile() as a
# value, run over a battery of subjects, and its answers reduced to two
# checksums, so one line stands for the pattern. tests/unit/stdlib.rs runs
# this program and compares its output with runtime_patterns.out, which is
# CPython 3.13's:
#
#   python3.13 -W ignore tests/fixtures/re/runtime_patterns.py \
#       > tests/fixtures/re/runtime_patterns.out
import re

TEXTS = ['', 'ab', 'abc abd', 'xaaab', 'Hello World 42', 'a\nb\n', 'ÉCOLE école aKs ſ k', 'x=1, y = 22 (3) <a> 日本 😀 ΣΑΣ σας ı İ']


def show(k: int, pattern: str, flags: int) -> None:
    try:
        p = re.compile(pattern, flags)
    except re.error as e:
        print(k, "re.error", str(e))
        return
    except ValueError as e:
        print(k, "ValueError", str(e))
        return
    except OverflowError as e:
        print(k, "OverflowError", str(e))
        return
    a = 7
    b = 11
    for text in TEXTS:
        m = p.search(text)
        line = "None"
        if m is not None:
            line = str(m.span()) + str(m.groups()) + str(m.groupdict()) + str(m.lastindex) + str(m.lastgroup)
        line = line + str(p.fullmatch(text) is not None) + str(p.match(text) is not None)
        line = line + str([x.span() for x in p.finditer(text)])
        line = line + p.sub("<\\g<0>>", text) + str(p.subn("", text, count=2))
        for ch in line:
            a = (a * 31 + ord(ch)) % 65521
            b = (b * 37 + ord(ch)) % 65497
    print(k, p.groups, p.flags, str(p.groupindex), a, b)


if __name__ == "__main__":
    show(0, 'a', 0)
    show(1, 'a', 2)
    show(2, 'abc', 0)
    show(3, 'abc', 24)
    show(4, 'a+b', 0)
